private void onStateChanged(State oldState, State newState) {
        // The unknown state means we're still initializing, so level doesn't exist yet
        // ignore this state
        if (oldState == State.UNKNOWN) return;

        switch (state) {
            case OPEN:
                onBoxOpened();
                break;
            case CLOSED:
                onBoxClosed();
                break;
            case OPENING:
                onBoxOpening();
                break;
            case CLOSING:
                onBoxClosing();
                break;
            default:
        }
    }

